import {
  DATA_TABLE_ACTION_COLUMN_ID,
  DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID,
  DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID,
  DATA_TABLE_SUB_ROW_TRIGGER_ID,
} from '../DataTable/constants.js';
import type { ColumnMinInstance } from '../types/internal-table-types.js';
import type {
  ColumnGroup,
  SingleColumn,
  TableColumn,
} from '../types/shared-table-types.js';

export const idOrAccessorErrorMessage =
  'Error: A column ID (or string accessor) is required!';

/**
 * This function returns the id, or if that's not defined, the corresponding accessor.
 * - If a column has a function accessor, it is required to define an id.
 * Therefore, if no id is defined, the accessor has to be a string.
 *  - If it is a single column and there is a function accessor and no id then undefined
 * will be returned.
 *  - If it is a column group with no id then undefined will be returned.
 *
 * @param column - column of which to get the id or string accessor
 * @returns string id, string accessor
 * @throws error if there is no id or string accessor
 */
export function getIdOrStringAccessor(
  column: TableColumn | ColumnMinInstance,
): string {
  const singleCol = column as SingleColumn;
  const result =
    singleCol.id ||
    (hasStringAccessor(singleCol) ? (singleCol.accessor as string) : undefined);

  if (result === undefined) {
    throw Error(idOrAccessorErrorMessage);
  }

  return result;
}

/**
 * Checks if the column has an accessor of type string. If so returns true, otherwise returns false.
 *
 * @param column - column to check
 * @returns true if the column has a string accessor
 */
export function hasStringAccessor(column: SingleColumn): boolean {
  if (column.accessor && typeof column.accessor === 'string') {
    return true;
  }
  return false;
}

/**
 * Checks if the column is a selectable/expandable/sub row trigger.
 *
 * @param id - column id
 */
export function getIsPrefixColumn(id: string): boolean {
  return (
    id.includes(DATA_TABLE_EXPANDABLE_ROW_TRIGGER_ID) ||
    id.includes(DATA_TABLE_SELECTABLE_ROW_TRIGGER_ID) ||
    id.includes(DATA_TABLE_SUB_ROW_TRIGGER_ID)
  );
}

/**
 * Finds the column instance that matches the given accessor or id.
 * @param columns - all table columns
 * @param accessorOrId - accessor or id of desired column
 *
 * @returns found column or undefined if none found
 */
export function findColumnInstance(
  columns: ColumnMinInstance[],
  accessorOrId: string,
): ColumnMinInstance | undefined {
  for (const current of columns) {
    if (current.id === accessorOrId) {
      return current;
    } else if (current?.parent?.id === accessorOrId) {
      return current.parent;
    }
  }
  return undefined;
}

/**
 * Checks if the column is a suffix column (currently only an action column).
 *
 * @param id - column id
 */
export function getIsSuffixColumn(id: string): boolean {
  return id.includes(DATA_TABLE_ACTION_COLUMN_ID);
}

/**
 * Checks if column can be excluded from things like visibility
 * configuration and downloading to CSV. Includes prefix and suffix columns.
 * @param id - column id
 */
export function getIsExcludableColumn(id: string): boolean {
  return id !== undefined && (getIsPrefixColumn(id) || getIsSuffixColumn(id));
}

/**
 *
 * @param id - id of column
 * @returns true if this is the id of the action column
 */
export function isActionColumn(id: string): boolean {
  return id.includes(DATA_TABLE_ACTION_COLUMN_ID);
}

/**
 * Finds columns with the given accessor or id.
 * @param columns - all table columns
 * @param accessorOrId - accessor or id of desired column
 *
 * @returns found column or undefined if none found
 */
export function findColumn(
  columns: TableColumn[],
  accessorOrId: string,
): { col: TableColumn; level: number } | undefined {
  return findColumnInternal(columns, accessorOrId, 0);
}

/**
 * Searches recursively in sub columns for column with the given accessor or id.
 * @param columns - at top level, all table columns or group of columns at lower level
 * @param accessorOrId - accessor or id of desired column
 * @param currentLevel - 0 for top level
 * @param parent - if true returns the parent group of the found column instead of the column itself (undefined if no parent group)
 *
 * @returns found column or undefined if none found
 */
export function findColumnInternal(
  columns: TableColumn[],
  accessorOrId: string,
  currentLevel: number,
  parent: boolean = false,
): { col: TableColumn; level: number } | undefined {
  for (const current of columns) {
    const column = current as SingleColumn;
    const group = current as ColumnGroup;
    if (column.accessor === accessorOrId || column.id === accessorOrId) {
      return { col: column, level: currentLevel };
    } else if (group.columns) {
      const columnsResult = findColumnInternal(
        group.columns,
        accessorOrId,
        currentLevel + 1,
      );
      if (columnsResult) {
        if (parent) {
          columnsResult.col = group;
          columnsResult.level = columnsResult.level - 1;
        }
        return columnsResult;
      }
    }
  }
  return undefined;
}

/**
 * Inserts an additonal column, e.g. expandable, subrows, selectable. First checks
 * if another column with the same column id already exists and if yes, reorders that one.
 * It is possible to specify column ids that the column should be inserted after.
 *
 * @param columns - all existing columns
 * @param column - column to insert
 * @param afterColIds - column ids after which the column should be inserted
 */
export function insertColumn(
  columns: { id?: string }[],
  column: { id?: string },
  afterColIds?: string[],
) {
  const newColumns = [...columns];

  // Check if the column array already contains a column with the same id
  const existingColumnIndex = newColumns.findIndex(
    (existingColumn) => existingColumn.id === column.id,
  );

  const columnToAdd =
    existingColumnIndex === -1
      ? column
      : newColumns.splice(existingColumnIndex, 1)[0];

  // find the index where the column should be inserted
  const index = afterColIds
    ? newColumns.filter((column) => afterColIds.includes(column.id || ''))
        .length
    : 0;
  newColumns.splice(index, 0, columnToAdd);
  return newColumns;
}

/**
 * Inserts an column id, e.g. expandable, subrows, selectable to an array of ordered column ids, if it does not exist yet.
 * It is possible to specify column ids that the new one should be inserted after.
 *
 * @param columnIds - ordered column ids
 * @param columnId - column id to insert
 * @param afterColIds - column ids after which the new id should be inserted
 */
export function insertColumnId(
  columnIds: string[],
  columnId: string,
  afterColIds?: string[],
) {
  // do nothing if columnIds is empty or it was already added
  if (columnIds.length === 0 || columnIds.includes(columnId)) {
    return columnIds;
  }

  // find the index where the column should be inserted
  const index = afterColIds
    ? columnIds.filter((id) => afterColIds.includes(id)).length
    : 0;
  columnIds.splice(index, 0, columnId);

  return columnIds;
}
